// Fan the batch out to one item per lead so each send is its own execution step.
const body = $json.body || {};
const messages = body.messages || {};
return Object.entries(messages).map(([lead_id, message]) => ({
  json: { lead_id, message, channel: body.channel || 'simulated' }
}));

// Collect every send result. A partial failure is reported, not hidden.
const results = $input.all().map((item) => item.json);
const sent = results.filter((r) => r.success).map((r) => r.lead_id);
const failed = results.filter((r) => !r.success);

return [{
  json: {
    success: failed.length === 0,
    error: failed.length ? failed.length + ' outreach send(s) failed' : '',
    sent,
    failed,
    delivery: 'simulated'
  }
}];
